--
-- Table structure for table `DgfmTaxref`
--

DROP TABLE IF EXISTS `DgfmTaxref`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `DgfmTaxref` (
  `taxnr` int unsigned NOT NULL,
  `sipnr` int unsigned NOT NULL,
  `rang` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Art | Synonym',
  `artname` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Voller Name mit Autor + Jahr',
  `gattung` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `art` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Epitheton',
  `binomial` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'gattung + " " + art',
  `autor` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jahr` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deutscher_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qualifizierungsvermerk` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `anmerkung` text COLLATE utf8mb4_unicode_ci,
  `rote_liste_d` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rote_liste_by` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gruppe` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `familie` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ordnung` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `klasse` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bemerkung` text COLLATE utf8mb4_unicode_ci,
  `gattungsinformation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`taxnr`),
  KEY `idx_sipnr` (`sipnr`),
  KEY `idx_binomial` (`binomial`),
  KEY `idx_rang` (`rang`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

